 p_id=>wwv_flow_imp.id(3413274244586445)
,p_name=>'HMS Menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LEVEL,',
'       MODULE_NAME label,',
'       CASE WHEN APEX_PAGE_NO IS NOT NULL',
'            THEN APEX_PAGE.GET_URL(p_page => APEX_PAGE_NO) END target,',
'       NULL is_current,',
'       ''fa '' || ICON_CLASS image',
'  FROM VW_APEX_MENU',
' WHERE PKG_APP_SESSION.can_yn(MODULE_CODE) = ''Y''',
' START WITH PARENT_MODULE_ID IS NULL',
'CONNECT BY PRIOR MODULE_ID = PARENT_MODULE_ID',
' ORDER SIBLINGS BY DISPLAY_ORDER'))
