'RETURN ''New Password didn t match''; ',
'END IF;',
'IF LENGTH(:P2_NEW_PWD) < 8 ',
'OR NOT REGEXP_LIKE(:P2_NEW_PWD,''[0-9]'') ',
'OR NOT REGEXP_LIKE(:P2_NEW_PWD,''[A-Z]'') THEN',
'   RETURN ''Min 8 character, 1 Uppercase + 1 number'';',
'END IF;',
'RETURN NULL;'))
